text:
{
  "characters": [
    {
      "id": "sumi",
      "want": "宛先の分かる郵便だけを、遅れずに届ける配達員でいたい。",
      "need": "届けられないものを抱えたまま、自分の記憶を信じることを覚える。",
      "fear": "町の記録が正しく、自分の覚えていることが間違いだと分かってしまうこと。",
      "wound": "十五年前、宛先を読み違えた手紙を届けた家が、その冬に空き家になった。",
      "secret": "閉山の日に局の棚から一通持ち出し、まだ返していない。",
      "principle": "宛先のあるものだけが郵便だ。宛先のないものは、預かっているだけだ。",
      "self_view": "几帳面で、人の家の事情には踏み込まない配達員。",
      "others_view": [
        "源じいから見れば、町で唯一、急がずに歩く人。",
        "あおいから見れば、閲覧簿に名前を書くのをいやがらない年上の女。"
      ],
      "predictions": [
        {"situation": "宛名のない手紙を棚の奥で見つけたとき", "choice": "三年の期限を確かめ、まず焼却の日取りを考える。"},
        {"situation": "差出人が十五年前の死者だと分かったとき", "choice": "役場の記録で裏を取ろうと、休日を返上して沢渡へ向かう。"},
        {"situation": "記録と記憶が食い違ったままだと知ったとき", "choice": "記録を直そうとせず、覚えている人に手紙を渡す。"}
      ],
      "speech": {
        "sample": "お届けものです。宛名が読めないので、こちらで預かっています。",
        "vocab": ["お届けもの", "預かり", "宛名", "棚"],
        "avoid": ["運命", "奇跡", "涙が止まらない"]
      },
      "arc": {
        "endpoint": "配達員のまま、宛先のない一通を自分の手で渡す。",
        "changed": ["宛先のない手紙は預かるだけだという扱いをやめる。"],
        "unchanged": ["歩いて届けるという仕事の作法。"]
      },
      "bans": ["感情を長々と説明する独白", "記録を破り捨てる衝動"]
    },
    {
      "id": "gen",
      "want": "坑道の最後の姿を、自分だけが覚えているままでいたい。",
      "need": "言いよどみをやめて、見たことを言葉にすること。",
      "fear": "話したことで、死んだ者の家族がもう一度傷つくこと。",
      "wound": "出水の日、東坑に誰かが残っているのを見て、報告しなかった。",
      "secret": "閉山の日、トオルを坑口まで見送ったのは自分だ。",
      "principle": "記録に残らないことは、なかったことにされる。だから口に出さない。",
      "self_view": "口数の少ない年寄りで、町の厄介者。",
      "others_view": [
        "スミから見れば、聞けば答えるが、聞かなければ何も言わない人。",
        "あおいから見れば、閲覧簿の同じ欄に何度も名前を残す人。"
      ],
      "predictions": [
        {"situation": "手紙の差出人の名を聞かされたとき", "choice": "知らないと答え、茶を淹れ直す。"},
        {"situation": "記録の死者欄が零だと聞かされたとき", "choice": "笑って、零で結構だと言う。"},
        {"situation": "点検の同行を頼まれたとき", "choice": "断らずに長靴を持ち出す。"}
      ],
      "speech": {
        "sample": "坑道のことは、記録に訊いてくれ。わしの話は当てにならん。",
        "vocab": ["坑道", "記録", "当てにならん", "茶"],
        "avoid": ["昔はよかった", "教えてやろう"]
      },
      "arc": {
        "endpoint": "坑口の前で、自分が見送った日のことを話す。",
        "changed": ["記録に任せるという言い訳をやめる。"],
        "unchanged": ["誰かを責める話はしないという頑固さ。"]
      },
      "bans": ["泣き崩れる場面", "手紙の内容を代弁すること"]
    },
    {
      "id": "aoi",
      "want": "記録を汚さず、閉じられたままの帳面を守りたい。",
      "need": "記録の外にある証言にも、同じ重さがあると認めること。",
      "fear": "自分の書いた一行で、町の過去が別のものになること。",
      "wound": "前任の記録係が、異説を注記した頁を切り取って辞めた。",
      "secret": "切り取られた頁の写しを、私物の手帳に挟んでいる。",
      "principle": "記録は直さない。直すなら、別の頁に書く。",
      "self_view": "若いが几帳面な記録係。",
      "others_view": [
        "スミから見れば、閲覧簿の字が丁寧すぎる人。",
        "源じいから見れば、年寄りの話を最後まで聞く役場の子。"
      ],
      "predictions": [
        {"situation": "死者欄が零の記録を見せられたとき", "choice": "零と書いたのは誰かを調べる。"},
        {"situation": "訂正を求められたとき", "choice": "訂正ではなく注記なら書けると答える。"},
        {"situation": "写しの存在を問われたとき", "choice": "手帳ごと机の上に置く。"}
      ],
      "speech": {
        "sample": "この頁は直せません。別の頁に、注記として書くことならできます。",
        "vocab": ["頁", "注記", "閲覧簿", "支所"],
        "avoid": ["真相", "すべてお見通し"]
      },
      "arc": {
        "endpoint": "注記の頁を新しく起こし、そこに自分の名前を書く。",
        "changed": ["記録を守ることを、黙る理由にしない。"],
        "unchanged": ["元の記録を書き換えないという規律。"]
      },
      "bans": ["記録を改ざんする", "年長者を子ども扱いする話し方"]
    },
    {
      "id": "toru",
      "want": "母に、自分が町を出た日の理由だけは知ってほしかった。",
      "need": "許されることではなく、読まれること。",
      "fear": "書いたことが、誰にも読まれないまま焼かれること。",
      "wound": "出水のあと、東坑の復旧を手伝うと言い出せなかった。",
      "secret": "閉山の日に町を出るつもりで、三通とも書き置いた。",
      "principle": "渡せないなら、書いて残すしかない。",
      "self_view": "町に残る資格のない男。",
      "others_view": [
        "源じいから見れば、坑口で何度も立ち止まる若い衆。",
        "スミから見れば、十五年前に配達先を間違えた家の跡取り。"
      ],
      "predictions": [
        {"situation": "宛名を書く欄の前で", "choice": "宛名を書かずに、日付だけを入れる。"},
        {"situation": "切手を貼る段になって", "choice": "貼らずに封をし、棚の奥に置く。"},
        {"situation": "町を出る直前", "choice": "坑口に寄ってから駅へ向かう。"}
      ],
      "speech": {
        "sample": "宛名は書かない。書けば、届かなかったときに嘘になる。",
        "vocab": ["宛名", "封", "日付"],
        "avoid": ["永遠に", "魂"]
      },
      "arc": {
        "endpoint": "亡くなった後も、三通の手紙だけが残る。",
        "changed": ["町を出る理由を、書き残すことに変えた。"],
        "unchanged": ["宛名を書かないという選択。"]
      },
      "bans": ["幽霊として現れて語る", "現在の場面で行為する"]
    }
  ]
}
